function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 100000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 entries.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > n)) return 'Each query is a node label between 1 and n.';
  return null;
}

