function numberOfNodes(n, queries) {
  const flipped = new Array(n + 1).fill(0);
  for (const query of queries) {
    flipped[query] ^= 1;
  }

  function dfs(node, parity) {
    if (node > n) {
      return 0;
    }
    const value = parity ^ flipped[node];
    const left = dfs(2 * node, value);
    const right = dfs(2 * node + 1, value);
    return value + left + right;
  }

  return dfs(1, 0);
}

