function numberOfNodes(n, queries) {
  const values = new Array(n + 1).fill(0);
  for (const q of queries) {
    for (let v = 1; v <= n; v++) {
      let up = v;
      while (up > q) up = Math.floor(up / 2);
      if (up === q) values[v] = 1 - values[v];
    }
  }
  let count = 0;
  for (let v = 1; v <= n; v++) count += values[v];
  return count;
}

