function generate(rand, size) {
  const n = size === 'large' ? 90000 + Math.floor(rand() * 10001) : 1 + Math.floor(rand() * 20);
  const m = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  // Small inputs often reuse a few labels so that repeated toggles cancel out.
  const pool = Math.max(1, Math.min(n, size === 'large' ? n : 1 + Math.floor(rand() * n)));
  const queries = Array.from({ length: m }, () => 1 + Math.floor(rand() * pool));
  return [n, queries];
}
